/**
 * Machine-readable marking of AI-generated content (AGENTS.md §7.5, AI Act art. 50(2)): JSON-LD
 * (schema.org) describing the generated analysis, its provenance and the original contribution
 * it is based on. The same facts are exported as `ai_generated`, `ai_model`, `ai_provider`,
 * `generated_at`, `analysis_version`, `human_reviewed` in the open data files (§7.4).
 */

import { CONTRIBUTOR_ATTRIBUTION, LICENCE_URL } from "./legal";

/** IPTC digital source type for content generated by a trained model. */
export const IPTC_TRAINED_ALGORITHMIC_MEDIA =
  "https://cv.iptc.org/newscodes/digitalsourcetype/trainedAlgorithmicMedia";

export const AI_PROVIDER = "Mistral AI";

export interface AiAnalysisMarking {
  /** Neutral title of the analysed idea. */
  title: string;
  /** Canonical URL of the idea page. */
  url: string;
  /** Model identifier, e.g. "mistral-large-latest". */
  model: string;
  /** Generation date (ISO). */
  generatedAt: string;
  analysisVersion: string;
}

export type AiJsonLd = Record<string, unknown>;

/** schema.org description of a generated analysis. */
export function aiAnalysisJsonLd(marking: AiAnalysisMarking): AiJsonLd {
  return {
    "@context": "https://schema.org",
    "@type": "CreativeWork",
    name: marking.title,
    url: marking.url,
    inLanguage: "fr",
    dateModified: marking.generatedAt,
    license: LICENCE_URL,
    digitalSourceType: IPTC_TRAINED_ALGORITHMIC_MEDIA,
    creator: {
      "@type": "SoftwareApplication",
      name: marking.model,
      provider: { "@type": "Organization", name: AI_PROVIDER },
    },
    isBasedOn: {
      "@type": "CreativeWork",
      name: CONTRIBUTOR_ATTRIBUTION,
      url: `${marking.url}#texte-original`,
    },
    additionalProperty: [
      { "@type": "PropertyValue", name: "ai_generated", value: true },
      { "@type": "PropertyValue", name: "human_reviewed", value: false },
      { "@type": "PropertyValue", name: "ai_provider", value: AI_PROVIDER },
      { "@type": "PropertyValue", name: "analysis_version", value: marking.analysisVersion },
    ],
  };
}

/**
 * Serialises JSON-LD for an inline script: `<`, `>` and `&` are escaped as Unicode sequences,
 * which JSON parsers read back unchanged, so no text can close the element or open a comment.
 */
export function aiJsonLdScript(data: AiJsonLd): string {
  return JSON.stringify(data)
    .replace(/</g, "\\u003c")
    .replace(/>/g, "\\u003e")
    .replace(/&/g, "\\u0026")
    .replace(/\u2028/g, "\\u2028")
    .replace(/\u2029/g, "\\u2029");
}
